+  >  egin{figure}[ht] \centering  egin{tikzpicture}[ node distance=10mm, every node/.style={font=\small}, box/.style={draw,rounded corners=2pt,align=center,text width=9.6cm,inner sep=5pt}, >=Stealth] 
ode[box] (digits) {Integer product\radix-digit convolution}; 
ode[box,below=of digits] (prime) {Cyclic convolution on distinct prime axes}; 
ode[box,below=of prime] (power) {Normalized convolution on power-of-two axes}; 
ode[box,below=of power] (ring) {Convolution over $\mathbb C[y]/(y^r+1)$\ synthetic transforms and packed polynomial products}; \draw[->] (digits)--node[right,font=\scriptsize,align=left] {Chinese-remainder\address map}(prime); \draw[->] (prime)--node[right,font=\scriptsize,align=left] {Gaussian resampling\and chirps}(power); \draw[->] (power)--node[right,font=\scriptsize,align=left] {last-coordinate\phase twist}(ring); \end{tikzpicture} \caption{The reductions connecting the tape procedures to multiplication. The arrows describe changes of problem and representation. Fast address interchanges organize the layouts, and simultaneous butterfly layers accelerate the synthetic transforms. Solving the final polynomial-ring convolution evaluates the transforms needed in the preceding stages. Known rescalings, rounding, and carry propagation then recover the exact integer product.} \label{fig:multiplication-flow} \end{figure}

